static_assert(std::is_standard_layout_v<tim2_p>);
static_assert(offsetof(tim2_p, cr1) == 0);
static_assert(offsetof(tim2_p, cr2) == 4);
static_assert(offsetof(tim2_p, smcr) == 8);
static_assert(offsetof(tim2_p, dier) == 12);
static_assert(offsetof(tim2_p, sr) == 16);
